//! Parity tests against BoTorch reference fixtures
//! (generated by `scripts/generate_fixtures.py`).
//!
//! Run with `cargo test --test parity -- --nocapture` to print the error
//! tables. Errors are mixed elementwise/normwise relative errors (see
//! `common::rel_err`).

mod common;

use botorch_core::{fit_gpytorch_mll, ExactMarginalLogLikelihood, FitOptions, FitStatus, Matrix};
use common::*;

/// Tolerance for deterministic quantities (kernels, transforms, MLL, posteriors).
const RTOL: f64 = 1e-10;

/// Absolute agreement threshold for gradient entries (see `Report::check_slices_atol`).
const GRAD_ATOL: f64 = 1e-14;

fn scalar_err(a: f64, e: f64) -> f64 {
    (a - e).abs() / e.abs().max(1e-300)
}

fn rows(m: &Matrix, start: usize, count: usize) -> Matrix {
    m.rows(start, count).into_owned()
}

#[test]
fn parity_parameter_layout_and_defaults() {
    let mut r = Report::default();
    for f in load_fixtures() {
        let model = build_model(&f);
        assert_eq!(
            model.parameter_names(),
            f.param_names,
            "{}: parameter names",
            f.name
        );
        r.check_slices(
            &f.name,
            "default raw params",
            model.raw_parameters().as_slice(),
            &f.default_raw_params,
            0.0,
        );
        let mll = ExactMarginalLogLikelihood::new(&model);
        let (v, g) = mll
            .value_and_grad(model.raw_parameters().as_slice())
            .unwrap();
        r.check(
            &f.name,
            "default mll value",
            scalar_err(v, f.default_mll.value),
            RTOL,
        );
        r.check_slices_atol(
            &f.name,
            "default mll grad",
            g.as_slice(),
            &f.default_mll.grad,
            RTOL,
            GRAD_ATOL,
        );
        assert_eq!(mll.value().unwrap(), v);
    }
    r.finish("default initialization");
}

#[test]
fn parity_transforms() {
    let mut r = Report::default();
    for f in load_fixtures() {
        let model = build_model(&f);
        let t = &f.transformed;
        r.check_slices(
            &f.name,
            "train_x transformed",
            &matrix_rows(model.transformed_train_inputs()),
            &flatten(&t.train_x),
            RTOL,
        );
        r.check_slices(
            &f.name,
            "train_y transformed",
            model.transformed_train_targets().as_slice(),
            &t.train_y,
            RTOL,
        );
        if let Some(offset) = &t.normalize_offset {
            let tf = model.input_transform().expect("normalize");
            r.check_slices(
                &f.name,
                "normalize offset",
                tf.offset().as_slice(),
                offset,
                RTOL,
            );
            let coef = t.normalize_coefficient.as_ref().unwrap();
            r.check_slices(
                &f.name,
                "normalize coefficient",
                tf.coefficient().as_slice(),
                coef,
                RTOL,
            );
            let xt = tf.transform(&matrix(&f.test_x)).unwrap();
            r.check_slices(
                &f.name,
                "test_x transformed",
                &matrix_rows(&xt),
                &flatten(&t.test_x),
                RTOL,
            );
        } else {
            assert!(model.input_transform().is_none());
        }
        if let Some(mean) = &t.standardize_mean {
            let st = model.outcome_transform().expect("standardize");
            r.check_slices(&f.name, "standardize mean", st.means(), mean, RTOL);
            r.check_slices(
                &f.name,
                "standardize std",
                st.stdvs(),
                t.standardize_std.as_ref().unwrap(),
                RTOL,
            );
        } else {
            assert!(model.outcome_transform().is_none());
        }
        if let Some(yvar) = &t.train_yvar {
            r.check_slices(
                &f.name,
                "fixed noise transformed",
                model.likelihood_noise().as_slice(),
                yvar,
                RTOL,
            );
        }
    }
    r.finish("transforms");
}

#[test]
fn parity_kernels() {
    let mut r = Report::default();
    for f in load_fixtures() {
        let mut model = build_model(&f);
        model.set_raw_parameters(&f.raw_params).unwrap();
        let kernel = model.kernel().unwrap();
        r.check_slices(
            &f.name,
            "lengthscale",
            kernel.lengthscale().as_slice(),
            &f.kernel.lengthscale,
            RTOL,
        );
        match (kernel.outputscale(), f.kernel.outputscale) {
            (Some(a), Some(e)) => r.check(&f.name, "outputscale", scalar_err(a, e), RTOL),
            (None, None) => {}
            other => panic!("{}: outputscale mismatch {other:?}", f.name),
        }
        r.check_slices(
            &f.name,
            "likelihood noise",
            model.likelihood_noise().as_slice(),
            &f.kernel.likelihood_noise,
            RTOL,
        );

        let x_tf = model.transformed_train_inputs().clone();
        let xt_tf = matrix(&f.transformed.test_x);
        let k = kernel.covariance_symmetric(&x_tf).unwrap();
        r.check_slices(
            &f.name,
            "K(X, X)",
            &matrix_rows(&k),
            &flatten(&f.kernel.k_train),
            RTOL,
        );
        let kc = kernel.covariance(&xt_tf, &x_tf).unwrap();
        r.check_slices(
            &f.name,
            "K(X*, X)",
            &matrix_rows(&kc),
            &flatten(&f.kernel.k_test_train),
            RTOL,
        );
        assert!(kernel
            .diag(&x_tf)
            .unwrap()
            .iter()
            .zip(k.diagonal().iter())
            .all(|(a, b)| a == b));

        let grads = kernel.hyperparameter_gradients(&x_tf).unwrap();
        r.check_slices(
            &f.name,
            "K from gradients()",
            &matrix_rows(&grads.covariance),
            &matrix_rows(&k),
            1e-15,
        );
        let layout = model.parameter_layout();
        for (name, jac) in &f.kernel.dk_draw {
            if name.ends_with("raw_lengthscale") {
                let mut actual = Vec::new();
                let mut expected = Vec::new();
                for (j, idx) in layout.lengthscale_range().enumerate() {
                    let td = f.transform_derivative[idx];
                    actual.extend(matrix_rows(&(&grads.lengthscale[j] * td)));
                    expected.extend(flatten(&jac[j]));
                }
                r.check_slices(&f.name, "dK/d raw_lengthscale", &actual, &expected, RTOL);
            } else if name.ends_with("raw_outputscale") {
                let td = f.transform_derivative[layout.outputscale_index().unwrap()];
                let ds = grads.outputscale.as_ref().expect("outputscale gradient");
                r.check_slices(
                    &f.name,
                    "dK/d raw_outputscale",
                    &matrix_rows(&(ds * td)),
                    &flatten(&jac[0]),
                    RTOL,
                );
            } else {
                panic!("unexpected kernel parameter {name}");
            }
        }
    }
    r.finish("kernels");
}

#[test]
fn parity_mll() {
    let mut r = Report::default();
    for f in load_fixtures() {
        let mut model = build_model(&f);
        model.set_raw_parameters(&f.raw_params).unwrap();
        let mll = ExactMarginalLogLikelihood::new(&model);
        let (v, g) = mll.value_and_grad(&f.raw_params).unwrap();
        r.check(&f.name, "mll value", scalar_err(v, f.mll.value), RTOL);
        r.check_slices_atol(
            &f.name,
            "mll grad",
            g.as_slice(),
            &f.mll.grad,
            RTOL,
            GRAD_ATOL,
        );
        r.check(
            &f.name,
            "mll value (model params)",
            scalar_err(mll.value().unwrap(), f.mll.value),
            RTOL,
        );
    }
    r.finish("exact marginal log likelihood");
}

#[test]
fn parity_posterior() {
    let mut r = Report::default();
    for f in load_fixtures() {
        let mut model = build_model(&f);
        model.set_raw_parameters(&f.raw_params).unwrap();
        let xt = matrix(&f.test_x);
        let q = xt.nrows();
        let (mut mean, mut var, mut var_noisy) = (Vec::new(), Vec::new(), Vec::new());
        for i in 0..q {
            let x = rows(&xt, i, 1);
            let p = model.posterior(&x, false).unwrap();
            let pn = model.posterior(&x, true).unwrap();
            mean.push(p.mean[0]);
            var.push(p.variance()[0]);
            var_noisy.push(pn.variance()[0]);
            assert!(
                (pn.covariance[(0, 0)] - p.covariance[(0, 0)] - model.observation_noise()).abs()
                    < 1e-12 * (1.0 + pn.covariance[(0, 0)].abs())
            );
        }
        let pf = &f.posterior;
        r.check_slices(&f.name, "q=1 mean", &mean, &pf.mean, RTOL);
        r.check_slices(&f.name, "q=1 variance", &var, &pf.variance, RTOL);
        r.check_slices(
            &f.name,
            "q=1 variance (obs noise)",
            &var_noisy,
            &pf.variance_noisy,
            RTOL,
        );

        let qj = pf.joint.mean.len();
        let xj = rows(&xt, 0, qj);
        let pj = model.posterior(&xj, false).unwrap();
        let pjn = model.posterior(&xj, true).unwrap();
        r.check_slices(
            &f.name,
            "joint mean",
            pj.mean.as_slice(),
            &pf.joint.mean,
            RTOL,
        );
        r.check_slices(
            &f.name,
            "joint covariance",
            &matrix_rows(&pj.covariance),
            &flatten(&pf.joint.covariance),
            RTOL,
        );
        r.check_slices(
            &f.name,
            "joint covariance (obs noise)",
            &matrix_rows(&pjn.covariance),
            &flatten(&pf.joint.covariance_noisy),
            RTOL,
        );
    }
    r.finish("posterior");
}

#[test]
fn parity_posterior_gradients() {
    let mut r = Report::default();
    for f in load_fixtures() {
        let mut model = build_model(&f);
        model.set_raw_parameters(&f.raw_params).unwrap();
        let xt = matrix(&f.test_x);
        let (q, d) = xt.shape();
        let pf = &f.posterior;
        let (mut mean, mut var, mut dm, mut dv) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
        for i in 0..q {
            let x: Vec<f64> = xt.row(i).iter().copied().collect();
            let (m, v, dmi, dvi) = model.posterior_q1_with_grad(&x).unwrap();
            mean.push(m);
            var.push(v);
            dm.extend(dmi.iter());
            dv.extend(dvi.iter());
        }
        r.check_slices(&f.name, "q=1 mean (grad api)", &mean, &pf.mean, RTOL);
        r.check_slices(&f.name, "q=1 variance (grad api)", &var, &pf.variance, RTOL);
        r.check_slices(&f.name, "q=1 dmean/dx", &dm, &flatten(&pf.dmean_dx), RTOL);
        r.check_slices(
            &f.name,
            "q=1 dvariance/dx",
            &dv,
            &flatten(&pf.dvariance_dx),
            RTOL,
        );

        let qj = pf.joint.mean.len();
        let xj = rows(&xt, 0, qj);
        let g = model.joint_posterior_with_grad(&xj).unwrap();
        r.check_slices(
            &f.name,
            "joint mean (grad api)",
            g.mean.as_slice(),
            &pf.joint.mean,
            RTOL,
        );
        r.check_slices(
            &f.name,
            "joint covariance (grad api)",
            &matrix_rows(&g.covariance),
            &flatten(&pf.joint.covariance),
            RTOL,
        );
        assert_eq!(g.dmean.len(), qj * d);
        assert_eq!(g.dcov.len(), qj * d);
        let (mut dm_a, mut dm_e, mut dc_a, mut dc_e) =
            (Vec::new(), Vec::new(), Vec::new(), Vec::new());
        for p in 0..qj {
            for k in 0..d {
                let j = p * d + k;
                for a in 0..qj {
                    dm_a.push(g.dmean[j][a]);
                    dm_e.push(pf.joint.dmean_dx[a][p][k]);
                    for b in 0..qj {
                        dc_a.push(g.dcov[j][(a, b)]);
                        dc_e.push(pf.joint.dcov_dx[a][b][p][k]);
                    }
                }
            }
        }
        r.check_slices(&f.name, "joint dmean/dx", &dm_a, &dm_e, RTOL);
        r.check_slices(&f.name, "joint dcov/dx", &dc_a, &dc_e, RTOL);
    }
    r.finish("posterior gradients");
}

#[test]
fn parity_fit() {
    let mut r = Report::default();
    println!(
        "{:40} {:>14} {:>14} {:>10} {:>6} {:>6} {:>9}",
        "fixture", "botorch loss", "rust loss", "excess", "it(bt)", "it(rs)", "min eig"
    );
    for f in load_fixtures() {
        let mut model = build_model(&f);
        assert_eq!(
            model.raw_parameters().as_slice(),
            f.fit.initial_raw_params.as_slice()
        );
        // The Rust MLL reproduces BoTorch's loss at BoTorch's optimum.
        let at_botorch = -ExactMarginalLogLikelihood::new(&model)
            .value_at(&f.fit.raw_params)
            .unwrap();
        r.check(
            &f.name,
            "loss at BoTorch optimum",
            scalar_err(at_botorch, f.fit.loss),
            RTOL,
        );

        let res = fit_gpytorch_mll(&mut model, FitOptions::default()).unwrap();
        assert_ne!(res.status, FitStatus::Failure);
        let loss = -ExactMarginalLogLikelihood::new(&model).value().unwrap();
        assert!(
            (loss - res.loss).abs() <= 1e-12 * (1.0 + loss.abs()),
            "{}: reported loss",
            f.name
        );
        let excess = res.loss - f.fit.loss;
        let min_eig = f
            .fit
            .hessian_eigenvalues
            .iter()
            .copied()
            .fold(f64::INFINITY, f64::min);
        println!(
            "{:40} {:>14.10} {:>14.10} {:>10.2e} {:>6} {:>6} {:>9.2e}  {}",
            f.name,
            f.fit.loss,
            res.loss,
            excess,
            f.fit.iterations,
            res.iterations,
            min_eig,
            res.message
        );
        // Final loss at most BoTorch's loss + 1e-6.
        r.check(&f.name, "fit loss excess", excess.max(0.0), 1e-6);
        // Hyperparameters agree where the optimum is well determined.
        if min_eig > 1e-2 {
            let fitted = model.raw_parameters();
            let err = fitted
                .iter()
                .zip(&f.fit.raw_params)
                .map(|(a, e)| (a - e).abs() / e.abs().max(1.0))
                .fold(0.0, f64::max);
            r.check(&f.name, "fit raw params", err, 2e-3);
            let xt = matrix(&f.test_x);
            let (mut mean, mut var) = (Vec::new(), Vec::new());
            for i in 0..xt.nrows() {
                let p = model.posterior(&rows(&xt, i, 1), false).unwrap();
                mean.push(p.mean[0]);
                var.push(p.variance()[0]);
            }
            r.check_slices(
                &f.name,
                "fitted posterior mean",
                &mean,
                &f.fit.posterior_mean,
                2e-3,
            );
            r.check_slices(
                &f.name,
                "fitted posterior variance",
                &var,
                &f.fit.posterior_variance,
                2e-2,
            );
        }
    }
    r.finish("fit_gpytorch_mll");
}
